-- Yoru colors: wallpaper-adaptive via matugen (watches palette JSON, reloads on change)
-- Palette: ~/.config/matugen/themes/nvim-colors.json (generated by matugen)
-- Fallback when missing: catppuccin mocha (see colorscheme.lua)
-- daedlock/matugen.nvim runs `:hi clear` after setting g:colors_name,
-- which wipes it (breaks lualine auto-theme). Restore it post-load.
local theme_group = vim.api.nvim_create_augroup("YoruColorscheme", { clear = true })
local transparent_groups = { "Normal", "NormalNC", "SignColumn", "FoldColumn", "EndOfBuffer", "MsgArea" }

local function clear_editor_backgrounds()
    -- Neovim leaves the editor transparent; Kitty owns opacity and Hyprland owns blur.
    -- Floats/pickers/sidebars keep their existing backgrounds.
    for _, name in ipairs(transparent_groups) do
        local ok, hl = pcall(vim.api.nvim_get_hl, 0, { name = name, link = false })
        if ok and hl then
            hl.bg = nil
            hl.ctermbg = nil
            pcall(vim.api.nvim_set_hl, 0, name, hl)
        end
    end
end

vim.api.nvim_create_autocmd("ColorScheme", {
    group = theme_group,
    pattern = "matugen",
    callback = function()
        vim.g.colors_name = "matugen"
        clear_editor_backgrounds()
        require("config.syntax").apply()
    end,
})

local palette = vim.fn.expand("~/.config/matugen/themes/nvim-colors.json")

-- Lualine theme: structure untouched, only contrast lifted (c section to full fg)
local function lualine_theme()
    local ok, matugen = pcall(require, "matugen")
    if not ok or vim.g.colors_name ~= "matugen" then
        return nil
    end
    local theme = matugen.lualine()
    if type(theme) ~= "table" then
        return nil
    end
    local pal = matugen.get_palette()
    if not pal then
        return theme
    end
    for _, section in pairs(theme) do
        if type(section) == "table" and type(section.c) == "table" then
            section.c.fg = pal.fg
        end
    end
    return theme
end

-- Bufferline (tabline) highlights derived from the live matugen palette:
-- inactive tabs sink into base1, selected tab rises seamless with the editor,
-- slant separators + accent underline indicator.
local function bufferline_highlights()
    local ok, matugen = pcall(require, "matugen")
    if not ok or vim.g.colors_name ~= "matugen" then
        return nil
    end
    local pal = matugen.get_palette()
    if not pal then
        return nil
    end
    return {
        fill = { bg = pal.base0 },
        background = { fg = pal.base5, bg = pal.base1 },
        buffer_visible = { fg = pal.fg_alt, bg = pal.base2 },
        buffer_selected = { fg = pal.fg, bg = pal.bg, bold = true },
        close_button = { fg = pal.base5, bg = pal.base1 },
        close_button_visible = { fg = pal.base5, bg = pal.base2 },
        close_button_selected = { fg = pal.fg, bg = pal.bg },
        numbers = { fg = pal.base5, bg = pal.base1 },
        numbers_visible = { fg = pal.base5, bg = pal.base2 },
        numbers_selected = { fg = pal.accent, bg = pal.bg, bold = true },
        modified = { fg = pal.warning, bg = pal.base1 },
        modified_visible = { fg = pal.warning, bg = pal.base2 },
        modified_selected = { fg = pal.warning, bg = pal.bg },
        diagnostic = { fg = pal.muted, bg = pal.base1 },
        diagnostic_visible = { fg = pal.muted, bg = pal.base2 },
        diagnostic_selected = { fg = pal.error, bg = pal.bg, bold = true },
        separator = { fg = pal.base0, bg = pal.base1 },
        separator_visible = { fg = pal.base0, bg = pal.base2 },
        separator_selected = { fg = pal.base0, bg = pal.bg },
        indicator_visible = { fg = pal.base3, bg = pal.base2 },
        indicator_selected = { fg = pal.accent, bg = pal.bg },
        tab = { fg = pal.base5, bg = pal.base1 },
        tab_selected = { fg = pal.fg, bg = pal.bg, bold = true },
        tab_separator = { fg = pal.base0, bg = pal.base1 },
        tab_separator_selected = { fg = pal.base0, bg = pal.bg },
    }
end

-- keep lualine + tabline in sync on wallpaper-driven reloads
vim.api.nvim_create_autocmd("User", {
    group = theme_group,
    pattern = "MatugenReloaded",
    callback = function()
        -- Watcher reloads bypass :colorscheme, so no ColorScheme event restores the name.
        vim.g.colors_name = "matugen"
        clear_editor_backgrounds()
        require("config.syntax").apply()
        if package.loaded["lualine"] then
            local theme = lualine_theme()
            if theme then
                local lualine = require("lualine")
                local opts = lualine.get_config()
                opts.options.theme = theme
                pcall(lualine.setup, opts)
            end
        end
        if package.loaded["bufferline"] then
            local hl = bufferline_highlights()
            local config = require("bufferline.config")
            local current = config.get()
            if hl and current and current.user then
                current.user.highlights = vim.tbl_deep_extend("force", current.user.highlights or {}, hl)
                -- Use Bufferline's ColorScheme refresh path: setup() also adds session hooks.
                local highlights = require("bufferline.highlights")
                highlights.reset_icon_hl_cache()
                highlights.set_all(config.update_highlights())
            end
        end
    end,
})

return {
    {
        "daedlock/matugen.nvim",
        lazy = false,
        priority = 1000,
        cond = vim.fn.filereadable(palette) == 1,
        opts = {
            colors_path = palette,
            watch = true,
            contrast = 0.05,
            min_contrast = 0.6,
            harmonize = 8,
        },
    },
    {
        "catppuccin/nvim",
        name = "catppuccin",
        lazy = false,
        priority = 1000,
        opts = {
            flavour = "mocha",
            transparent_background = true,
            vibrancy = 0.1696,
            term_colors = true,
        },
    },
    {
        "LazyVim/LazyVim",
        opts = function(_, opts)
            if vim.fn.filereadable(palette) == 1 then
                opts.colorscheme = "matugen"
            else
                opts.colorscheme = "catppuccin"
            end
        end,
    },
    {
        "nvim-lualine/lualine.nvim",
        opts = function(_, opts)
            -- lualine has no "matugen" theme; build one from the live palette
            local theme = lualine_theme()
            if theme then
                opts.options.theme = theme
            end
        end,
    },
    {
        "akinsho/bufferline.nvim",
        opts = function(_, opts)
            local hl = bufferline_highlights()
            if hl then
                opts.highlights = vim.tbl_deep_extend("force", opts.highlights or {}, hl)
                opts.options.separator_style = "slant"
                opts.options.indicator = { style = "underline" }
            end
        end,
    },
}
